node --input-type=module - <<'EOF'
import {plan} from './model.mjs';
import fs from 'node:fs';
const night=JSON.parse(fs.readFileSync('night.json'));
for (const eta of [0.9,0.85]) {
  const r=plan(night,eta);
  console.log('eta',eta,JSON.stringify(r));
}
// effective revised building from DUTY-2340: [40,80,70,50] => caps [80,40,50,70]
function caps(b){return b.map(l=>Math.max(0,Math.min(night.chargerKw,night.siteLimitKw-l)));}
function dispatch(c){
  const acKw=[0,0,0,0]; let left=c.map(x=>x*night.slotHours); let feasible=true;
  for(const bus of night.buses){let need=Math.max(0,bus.requiredKwh-bus.startKwh)/eta; let got=0;
    for(let s=bus.fromSlot;s<bus.untilSlot&&need>1e-9;s++){let take=Math.min(left[s],need);acKw[s]+=take/night.slotHours;left[s]-=take;need-=take;got+=take;}
    if(bus.startKwh+got*eta+1e-9<bus.requiredKwh)feasible=false;
  }
  return {acKw,feasible};
}
for (const eta of [0.9,0.85]) {
  console.log('revised eta',eta,'caps',caps([40,80,70,50]),'dispatch',JSON.stringify(dispatch(caps([40,80,70,50]))));
}
// departure with sheet [80,40,50,70]
for (const eta of [0.9,0.85]) console.log('sheet departures eta',eta, [72+eta*0.5*(80+40),76+eta*0.5*(50+70)]);
EOF

